CREATE TYPE "Role" AS ENUM ('MEMBER','BOARD');
CREATE TYPE "ScanMethod" AS ENUM ('CAMERA','USB','MANUAL');
CREATE TYPE "SyncStatus" AS ENUM ('NOT_APPLICABLE','PENDING','PROCESSING','SYNCED','FAILED','CONFLICT');
CREATE TYPE "PresenceStatus" AS ENUM ('UNKNOWN','PRESENT','NOT_PRESENT');
CREATE TYPE "OutboxStatus" AS ENUM ('PENDING','PROCESSING','COMPLETED','FAILED','DEAD');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"congressusUserId" TEXT NOT NULL UNIQUE,"congressusMemberId" INTEGER UNIQUE,"username" TEXT,"name" TEXT NOT NULL,"firstName" TEXT,"pictureUrl" TEXT,"memberNumber" TEXT,"memberStatus" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"role" "Role" NOT NULL DEFAULT 'MEMBER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "EventCache" ("id" TEXT PRIMARY KEY,"congressusEventId" INTEGER NOT NULL UNIQUE,"name" TEXT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"location" TEXT,"participationMode" TEXT NOT NULL DEFAULT 'single',"registrationCount" INTEGER NOT NULL DEFAULT 0,"closedAt" TIMESTAMP(3),"payload" JSONB,"syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EventParticipation" ("id" TEXT PRIMARY KEY,"congressusParticipationId" INTEGER NOT NULL UNIQUE,"eventId" TEXT NOT NULL REFERENCES "EventCache"("id") ON DELETE CASCADE,"congressusMemberId" INTEGER,"memberName" TEXT NOT NULL,"memberNumber" TEXT,"status" TEXT NOT NULL,"presence" "PresenceStatus" NOT NULL DEFAULT 'UNKNOWN',"tickets" JSONB,"syncedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "EventParticipation_eventId_congressusMemberId_idx" ON "EventParticipation"("eventId","congressusMemberId");
CREATE TABLE "CheckIn" ("id" TEXT PRIMARY KEY,"eventId" TEXT NOT NULL REFERENCES "EventCache"("id") ON DELETE RESTRICT,"memberId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"scannerId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"participationId" INTEGER,"ticketId" INTEGER,"method" "ScanMethod" NOT NULL,"exception" BOOLEAN NOT NULL DEFAULT false,"reason" TEXT,"checkedInAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"syncStatus" "SyncStatus" NOT NULL DEFAULT 'PENDING',"syncError" TEXT,"version" INTEGER NOT NULL DEFAULT 1,UNIQUE("eventId","memberId"));
CREATE INDEX "CheckIn_syncStatus_checkedInAt_idx" ON "CheckIn"("syncStatus","checkedInAt");
CREATE TABLE "SyncOutbox" ("id" TEXT PRIMARY KEY,"checkInId" TEXT NOT NULL UNIQUE,"eventCongressusId" INTEGER NOT NULL,"participationId" INTEGER,"ticketId" INTEGER,"payload" JSONB NOT NULL,"status" "OutboxStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3));
CREATE INDEX "SyncOutbox_status_availableAt_idx" ON "SyncOutbox"("status","availableAt");
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"actorId" TEXT REFERENCES "User"("id") ON DELETE SET NULL,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT NOT NULL,"before" JSONB,"after" JSONB,"reason" TEXT,"ipHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AuditLog_entityType_entityId_createdAt_idx" ON "AuditLog"("entityType","entityId","createdAt");
CREATE TABLE "SecurityEvent" ("id" TEXT PRIMARY KEY,"type" TEXT NOT NULL,"userId" TEXT,"ipHash" TEXT,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "SecurityEvent_type_createdAt_idx" ON "SecurityEvent"("type","createdAt");
CREATE TABLE "RateLimitBucket" ("key" TEXT PRIMARY KEY,"count" INTEGER NOT NULL,"windowStart" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL);
